const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], q = tok[1];
const ids = new Map(), arr = [];
for (let i = 0; i < n; i++) {
  const x = tok[2 + i];
  if (!ids.has(x)) ids.set(x, ids.size);
  arr.push(ids.get(x));
}
const qs = [];
for (let i = 0; i < q; i++) qs.push([tok[2 + n + 2 * i] - 1, tok[3 + n + 2 * i] - 1, i]);
const block = Math.max(1, Math.floor(n / Math.max(1, Math.sqrt(q))));
qs.sort((a, b) => {
  const ba = Math.floor(a[0] / block), bb = Math.floor(b[0] / block);
  if (ba !== bb) return ba - bb;
  return ba % 2 === 0 ? a[1] - b[1] : b[1] - a[1];
});
const cnt = new Array(ids.size).fill(0), ans = new Array(q).fill(0);
let distinct = 0, L = 0, R = -1;
const add = (i) => { if (cnt[arr[i]]++ === 0) distinct++; };
const rem = (i) => { if (--cnt[arr[i]] === 0) distinct--; };
for (const [l, r, i] of qs) {
  while (L > l) add(--L);
  while (R < r) add(++R);
  while (L < l) rem(L++);
  while (R > r) rem(R--);
  ans[i] = distinct;
}
console.log(ans.join("\n"));

