import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        HashMap<Long, Integer> ids = new HashMap<>();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            long x = (long) in.nval;
            Integer id = ids.get(x);
            if (id == null) { id = ids.size(); ids.put(x, id); }
            arr[i] = id;
        }
        int[] ql = new int[q], qr = new int[q];
        for (int i = 0; i < q; i++) {
            in.nextToken();
            ql[i] = (int) in.nval - 1;
            in.nextToken();
            qr[i] = (int) in.nval - 1;
        }
        final int block = Math.max(1, (int) (n / Math.max(1.0, Math.sqrt(q))));
        Integer[] idx = new Integer[q];
        for (int i = 0; i < q; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> {
            int ba = ql[a] / block, bb = ql[b] / block;
            if (ba != bb) return Integer.compare(ba, bb);
            return ba % 2 == 0 ? Integer.compare(qr[a], qr[b]) : Integer.compare(qr[b], qr[a]);
        });
        int[] cnt = new int[ids.size()];
        int[] ans = new int[q];
        int distinct = 0, L = 0, R = -1;
        for (int k : idx) {
            int l = ql[k], r = qr[k];
            while (L > l) { L--; if (cnt[arr[L]]++ == 0) distinct++; }
            while (R < r) { R++; if (cnt[arr[R]]++ == 0) distinct++; }
            while (L < l) { if (--cnt[arr[L]] == 0) distinct--; L++; }
            while (R > r) { if (--cnt[arr[R]] == 0) distinct--; R--; }
            ans[k] = distinct;
        }
        StringBuilder out = new StringBuilder();
        for (int x : ans) out.append(x).append('\n');
        System.out.print(out);
    }
}

