#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    vector<int> arr(n);
    unordered_map<long long, int> ids;
    for (int i = 0; i < n; i++) {
        long long x;
        scanf("%lld", &x);
        auto it = ids.find(x);
        if (it == ids.end()) it = ids.emplace(x, (int)ids.size()).first;
        arr[i] = it->second;
    }
    vector<int> ql(q), qr(q), idx(q);
    for (int i = 0; i < q; i++) { scanf("%d %d", &ql[i], &qr[i]); ql[i]--; qr[i]--; idx[i] = i; }
    int block = max(1, (int)(n / max(1.0, sqrt((double)q))));
    sort(idx.begin(), idx.end(), [&](int a, int b) {
        int ba = ql[a] / block, bb = ql[b] / block;
        if (ba != bb) return ba < bb;
        return (ba % 2 == 0) ? qr[a] < qr[b] : qr[a] > qr[b];
    });
    vector<int> cnt(ids.size(), 0), ans(q);
    int distinct = 0, L = 0, R = -1;
    for (int k : idx) {
        int l = ql[k], r = qr[k];
        while (L > l) { L--; if (cnt[arr[L]]++ == 0) distinct++; }
        while (R < r) { R++; if (cnt[arr[R]]++ == 0) distinct++; }
        while (L < l) { if (--cnt[arr[L]] == 0) distinct--; L++; }
        while (R > r) { if (--cnt[arr[R]] == 0) distinct--; R--; }
        ans[k] = distinct;
    }
    for (int x : ans) printf("%d\n", x);
    return 0;
}
